# Metas iniciales (NOM-015 diabetes, NOM-030 hipertension, NOM-037
# dislipidemias, NOM-008 obesidad). Las valida un medico antes del
# despliegue; ver docs/plans/cronicos-control.md.
METAS = {
    "DIABETES": [("hba1c", None, "7"), ("glucosa_capilar", "70", "130"),
                 ("ta_sistolica", None, "130"), ("ta_diastolica", None, "80")],
    "HIPERTENSION": [("ta_sistolica", None, "140"), ("ta_diastolica", None, "90")],
    "DISLIPIDEMIA": [("colesterol_total", None, "200"), ("ldl", None, "130"), ("trigliceridos", None, "150")],
    "OBESIDAD": [("imc", "18.5", "24.9")],
    "ERC": [("ta_sistolica", None, "130"), ("ta_diastolica", None, "80")],
}
DIAS_CONTROL = {"DISLIPIDEMIA": 180}


def sembrar(apps, schema_editor):
    ChronicProgram = apps.get_model("padrones", "ChronicProgram")
    ChronicControlGoal = apps.get_model("padrones", "ChronicControlGoal")
    for code, metas in METAS.items():
        program = ChronicProgram.objects.filter(code=code).first()
        if program is None:
            continue
        if code in DIAS_CONTROL:
            program.control_every_days = DIAS_CONTROL[code]
            program.save(update_fields=["control_every_days"])
        for parameter, min_value, max_value in metas:
            ChronicControlGoal.objects.get_or_create(
                program=program, parameter=parameter,
                defaults={"min_value": min_value, "max_value": max_value},
            )


def quitar(apps, schema_editor):
    apps.get_model("padrones", "ChronicControlGoal").objects.filter(program__code__in=list(METAS)).delete()


